export const animationStateLimits={machines:8,states:128,statesPerMachine:64,transitions:256,conditions:16,contexts:2048,poseBytes:64*1024*1024};
export const animationInterrupts={none:'중단 없음',current:'현재 상태',next:'다음 상태',currentNext:'현재 → 다음',nextCurrent:'다음 → 현재'};
export const animationBlendCurves={linear:'선형',smooth:'부드럽게',easeIn:'천천히 시작',easeOut:'천천히 끝'};
export const animationConditionOps={true:'참',false:'거짓',eq:'같음',ne:'다름',gt:'초과',ge:'이상',lt:'미만',le:'이하'};
const finite=(v,max=100000)=>Number.isFinite(v)&&Math.abs(v)<=max;
const name=v=>typeof v==='string'&&v.length>0&&v.length<=80&&!/[\x00-\x1f]/.test(v);
const event=v=>typeof v==='string'&&v.length<=80&&!/[\x00-\x1f]/.test(v);
export function validAnimationParameterValue(p,value){return ['float','int','enum'].includes(p?.type)?typeof value==='number'&&finite(value)&&(p.type==='float'||Number.isInteger(value))&&(p.type!=='enum'||p.values?.some(e=>e.value===value)):['bool','trigger'].includes(p?.type)&&typeof value==='boolean';}
export function validAnimationParameter(p){return p&&/^[A-Za-z_가-힣][\w가-힣]*$/.test(p.name)&&name(p.name)&&['float','int','bool','trigger','enum'].includes(p.type)&&(p.type!=='enum'||Array.isArray(p.values)&&p.values.length>0&&p.values.length<=64&&new Set(p.values.map(e=>e?.name)).size===p.values.length&&new Set(p.values.map(e=>e?.value)).size===p.values.length&&p.values.every(e=>e&&name(e.name)&&/^[A-Za-z_가-힣][\w가-힣]*$/.test(e.name)&&finite(e.value)&&Number.isInteger(e.value)))&&validAnimationParameterValue(p,p.value);}
export function makeAnimationState(label='State',x=180,y=140){const id='state_'+crypto.randomUUID();return {id,name:label,input:id.replaceAll('-','_'),x,y,speed:1,offset:0,resetOnEntry:true,onEnter:'',onExit:'',onFullyBlended:''};}
export function makeAnimationMachine(){const state=makeAnimationState('Idle');return {entry:state.id,maxTransitions:8,skipFirstTransition:false,reinitialize:true,states:[state],transitions:[]};}
export function addAnimationState(node,settings={}){const p=node.properties;let label=settings.name||'State',i=1;while(p.states.some(s=>s.name===label))label=(settings.name||'State')+i++;const state=makeAnimationState(label,settings.x??200,settings.y??160);p.states.push(state);return state;}
export function removeAnimationOwnedNodes(data,owned,required=new Set()){
  let changed;do{changed=false;for(const n of data.nodes)if(n.scope&&owned.has(n.scope.split('/')[0])&&!owned.has(n.id)){owned.add(n.id);changed=true;}}while(changed);
  const map=new Map(data.nodes.map(n=>[n.id,n])),keep=new Set(),visit=id=>{if(!owned.has(id)||keep.has(id)||required.has(id))return;keep.add(id);for(const source of Object.values(map.get(id).inputs))visit(source);};
  for(const n of data.nodes)if(!owned.has(n.id))for(const source of Object.values(n.inputs))visit(source);
  const deleted=new Set([...owned].filter(id=>!keep.has(id)||required.has(id)));data.nodes=data.nodes.filter(n=>!deleted.has(n.id));const scopes=new Set(data.nodes.filter(n=>n.type==='stateMachine').flatMap(n=>n.properties.states.map(s=>n.id+'/'+s.id)));
  for(const n of data.nodes){if(n.scope&&!scopes.has(n.scope))delete n.scope;for(const [input,source] of Object.entries(n.inputs))if(deleted.has(source))delete n.inputs[input];}
}
export function removeAnimationState(node,id,data){const p=node.properties;if(p.states.length<=1)throw Error('최소 한 상태가 필요해요.');if(!p.states.some(s=>s.id===id))throw Error('상태 ID를 확인하세요.');const state=p.states.find(s=>s.id===id);delete node.inputs[state.input];p.states=p.states.filter(s=>s.id!==id);p.transitions=p.transitions.filter(t=>t.from!==id&&t.to!==id);if(p.entry===id)p.entry=p.states[0].id;if(data)removeAnimationOwnedNodes(data,new Set(data.nodes.filter(n=>n.scope===node.id+'/'+id).map(n=>n.id)));}
export function addAnimationTransition(node,from,to,parameters=[]){const p=node.properties;if(from!=='any'&&!p.states.some(s=>s.id===from)||!p.states.some(s=>s.id===to))throw Error('전이 상태 ID를 확인하세요.');const parameter=parameters.find(p=>p.type==='bool'),t={id:'transition_'+crypto.randomUUID(),from,to,duration:.2,fixedDuration:true,offset:0,curve:'linear',priority:0,hasExitTime:!parameter,exitTime:.75,conditions:parameter?[{parameter:parameter.name,op:'true',value:true}]:[],interrupt:'current',ordered:true,allowSelf:false,onStart:'',onEnd:'',onInterrupt:''};p.transitions.push(t);return t;}
export function validAnimationMachine(p,parameters){
  try{if(!p||!Array.isArray(p.states)||!p.states.length||p.states.length>animationStateLimits.statesPerMachine||!Array.isArray(p.transitions)||p.transitions.length>animationStateLimits.transitions||!Number.isInteger(p.maxTransitions)||p.maxTransitions<1||p.maxTransitions>32||typeof p.skipFirstTransition!=='boolean'||typeof p.reinitialize!=='boolean')return false;
    const states=new Map(p.states.map(s=>[s?.id,s])),params=new Map(parameters.map(p=>[p.name,p.type]));if(states.size!==p.states.length||!states.has(p.entry)||new Set(p.states.map(s=>s.input)).size!==states.size||new Set(p.states.map(s=>s.name)).size!==states.size)return false;
    for(const s of states.values())if(!/^state_[A-Za-z0-9_-]+$/.test(s.id)||!name(s.name)||!/^state_[A-Za-z0-9_]+$/.test(s.input)||!finite(s.x)||!finite(s.y)||!finite(s.speed,100)||s.speed<0||!finite(s.offset,1000)||s.offset<0||typeof s.resetOnEntry!=='boolean'||![s.onEnter,s.onExit,s.onFullyBlended].every(event))return false;
    if(new Set(p.transitions.map(t=>t?.id)).size!==p.transitions.length)return false;
    for(const t of p.transitions){if(!/^transition_[A-Za-z0-9_-]+$/.test(t.id)||(t.from!=='any'&&!states.has(t.from))||!states.has(t.to)||!finite(t.duration,60)||t.duration<0||typeof t.fixedDuration!=='boolean'||!finite(t.offset,1000)||t.offset<0||!animationBlendCurves[t.curve]||!Number.isInteger(t.priority)||Math.abs(t.priority)>10000||typeof t.hasExitTime!=='boolean'||!finite(t.exitTime,1000)||t.exitTime<0||!animationInterrupts[t.interrupt]||typeof t.ordered!=='boolean'||typeof t.allowSelf!=='boolean'||![t.onStart,t.onEnd,t.onInterrupt].every(event)||!Array.isArray(t.conditions)||t.conditions.length>animationStateLimits.conditions||(!t.hasExitTime&&!t.conditions.length))return false;
      for(const c of t.conditions){const type=params.get(c?.parameter),parameter=parameters.find(p=>p.name===c.parameter);if(type==='enum'&&(!['eq','ne'].includes(c.op)||!validAnimationParameterValue(parameter,c.value)))return false;if(!type||!animationConditionOps[c.op]||(['bool','trigger'].includes(type)?!['true','false'].includes(c.op)||typeof c.value!=='boolean'||type==='trigger'&&c.op!=='true':!['eq','ne','gt','ge','lt','le'].includes(c.op)||!finite(c.value)||type==='int'&&!Number.isInteger(c.value)))return false;}
    }return true;
  }catch{return false;}
}
